#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct { float x, y, z; } Vec3;
typedef struct { Vec3 origin, direction; } Ray;
typedef struct { Vec3 center; float radius; } Sphere;
typedef struct { float t; Vec3 point; Vec3 normal; int hit; } HitRecord;

Vec3 vector_create(float x, float y, float z) {
    Vec3 v; v.x = x; v.y = y; v.z = z; return v;
}
Vec3 vector_add(Vec3 a, Vec3 b) {
    return vector_create(a.x + b.x, a.y + b.y, a.z + b.z);
}
Vec3 vector_subtract(Vec3 a, Vec3 b) {
    return vector_create(a.x - b.x, a.y - b.y, a.z - b.z);
}
Vec3 vector_multiply(Vec3 a, float s) {
    return vector_create(a.x * s, a.y * s, a.z * s);
}
float vector_dot(Vec3 a, Vec3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}
float vector_length(Vec3 a) {
    return sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}
Vec3 vector_normalize(Vec3 a) {
    float len = vector_length(a);
    return vector_create(a.x / len, a.y / len, a.z / len);
}
Ray ray_create(Vec3 origin, Vec3 direction) {
    Ray r; r.origin = origin; r.direction = vector_normalize(direction); return r;
}
Vec3 ray_at(Ray r, float t) {
    return vector_add(r.origin, vector_multiply(r.direction, t));
}

HitRecord sphere_intersect(Sphere sphere, Ray ray) {
    HitRecord rec;
    rec.t = 0.0f;
    rec.point = vector_create(0.0f, 0.0f, 0.0f);
    rec.normal = vector_create(0.0f, 0.0f, 0.0f);
    rec.hit = 0;

    Vec3 oc = vector_subtract(ray.origin, sphere.center);
    float a = vector_dot(ray.direction, ray.direction);
    float b = 2.0f * vector_dot(oc, ray.direction);
    float c = vector_dot(oc, oc) - sphere.radius * sphere.radius;
    float discriminant = b * b - 4 * a * c;

    if (discriminant < 0.0f) return rec;

    float t = (-b - sqrt(discriminant)) / (2.0f * a);
    if (t < 0.001f) {
        t = (-b + sqrt(discriminant)) / (2.0f * a);
        if (t < 0.001f) return rec;
    }
    rec.t = t;
    rec.point = ray_at(ray, t);
    rec.normal = vector_normalize(vector_subtract(rec.point, sphere.center));
    rec.hit = 1;
    return rec;
}

HitRecord plane_intersect(float plane_y, Ray ray) {
    HitRecord rec;
    rec.t = 0.0f;
    rec.point = vector_create(0.0f, 0.0f, 0.0f);
    rec.normal = vector_create(0.0f, 0.0f, 0.0f);
    rec.hit = 0;

    if (fabsf(ray.direction.y) < 0.0001f) return rec;
    float t = (plane_y - ray.origin.y) / ray.direction.y;
    if (t < 0.001f) return rec;

    rec.t = t;
    rec.point = ray_at(ray, t);
    rec.normal = vector_create(0.0f, 1.0f, 0.0f);
    rec.hit = 1;
    return rec;
}

Vec3 sky_color(Ray ray) {
    float t = 0.5f * (ray.direction.y + 1.0f);
    return vector_add(vector_multiply(vector_create(0.5f, 0.7f, 1.0f), t),
                      vector_multiply(vector_create(1.0f, 1.0f, 1.0f), 1.0f - t));
}

int is_in_shadow(Vec3 point, Vec3 light_dir, Sphere sphere) {
    Ray shadow_ray = ray_create(point, light_dir);
    HitRecord rec = sphere_intersect(sphere, shadow_ray);
    return rec.hit;
}

Vec3 trace(Ray ray, Sphere sphere, Vec3 light_dir) {
    HitRecord sphere_hit = sphere_intersect(sphere, ray);
    HitRecord plane_hit = plane_intersect(-1.5f, ray);

    HitRecord hit;
    int is_sphere;
    if (sphere_hit.hit && plane_hit.hit) {
        if (plane_hit.t > sphere_hit.t) { hit = sphere_hit; is_sphere = 1; }
        else { hit = plane_hit; is_sphere = 0; }
    } else if (sphere_hit.hit) {
        hit = sphere_hit; is_sphere = 1;
    } else if (plane_hit.hit) {
        hit = plane_hit; is_sphere = 0;
    } else {
        return sky_color(ray);
    }

    Vec3 shadow_origin = vector_add(hit.point, vector_multiply(hit.normal, 0.001f));
    float intensity;
    if (is_in_shadow(shadow_origin, light_dir, sphere)) {
        intensity = 0.2f;
    } else {
        float diffuse = fmax(vector_dot(hit.normal, light_dir), 0.0);
        intensity = diffuse * 0.8f + 0.2f;
    }

    if (is_sphere) {
        return vector_multiply(vector_create(1.0f, 0.2f, 0.2f), intensity);
    }
    int check = (int)(floor(hit.point.x) + floor(hit.point.z));
    float shade = (check % 2 == 0) ? 0.9f : 0.4f;
    return vector_multiply(vector_create(shade, shade, shade), intensity);
}

Vec3 **allocate_image(int width, int height) {
    Vec3 **image = (Vec3 **)malloc(height * sizeof(Vec3 *));
    for (int y = 0; y < height; y++)
        image[y] = (Vec3 *)malloc(width * sizeof(Vec3));
    return image;
}

void free_image(Vec3 **image, int height) {
    for (int y = 0; y < height; y++) free(image[y]);
    free(image);
}

void write_image(const char *filename, Vec3 **image, int width, int height) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", filename);
        return;
    }
    fprintf(f, "P3\n%d %d\n255\n", width, height);
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float r = fmin(fmax(image[y][x].x, 0.0), 1.0);
            float g = fmin(fmax(image[y][x].y, 0.0), 1.0);
            float b = fmin(fmax(image[y][x].z, 0.0), 1.0);
            fprintf(f, "%d %d %d\n", (int)(r * 255.99f), (int)(g * 255.99f),
                    (int)(b * 255.99f));
        }
    }
    fclose(f);
    fprintf(stderr, "Wrote image to %s\n", filename);
}

int main(void) {
    int width = 800;
    int height = 600;

    fprintf(stderr, "Creating high-resolution image: %dx%d\n", width, height);
    fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");

    Sphere sphere;
    sphere.center = vector_create(0.0f, -0.5f, -5.0f);
    sphere.radius = 1.0f;

    Vec3 light_dir = vector_normalize(vector_create(1.0f, 1.0f, -1.0f));

    float aspect = (float)width / (float)height;
    Vec3 origin = vector_create(0.0f, 0.0f, 0.0f);
    Vec3 horizontal = vector_create(2.0f * aspect, 0.0f, 0.0f);
    Vec3 vertical = vector_create(0.0f, 2.0f, 0.0f);
    Vec3 lower_left = vector_create(-aspect, -1.0f, -1.0f);

    Vec3 **image = allocate_image(width, height);

    fprintf(stderr, "Rendering high-resolution image...\n");

    for (int y = 0; y < height; y++) {
        fprintf(stderr, "\rProgress: %.1f%%", (float)y * 100.0f / (float)height);
        for (int x = 0; x < width; x++) {
            float u = (float)x / (float)(width - 1);
            float v = 1.0f - (float)y / (float)(height - 1);
            Vec3 dir = vector_add(vector_add(vector_multiply(horizontal, u),
                                             vector_multiply(vertical, v)),
                                  lower_left);
            Ray ray = ray_create(origin, dir);
            image[y][x] = trace(ray, sphere, light_dir);
        }
    }

    fprintf(stderr, "\nRendering complete\n");
    write_image("image.ppm", image, width, height);
    free_image(image, height);
    fprintf(stderr, "Done.\n");
    return 0;
}
